<?php require __DIR__.'/../../includes/admin_auth.php';$rows=db()->query("SELECT l.*,CONCAT(COALESCE(u.first_name,'System'),' ',COALESCE(u.last_name,'')) name FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 100")->fetchAll();$pageTitle='Activity logs';require __DIR__.'/../../includes/header.php';?><h1>Activity logs</h1><div class="panel"><table><tr><th>User</th><th>Action</th><th>Description</th><th>Entity</th><th>IP</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['action'])?></td><td><?=e($r['description'])?></td><td><?=e($r['entity_type'].' #'.$r['entity_id'])?></td><td><?=e($r['ip_address'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../../includes/footer.php'; ?>
